    private void DrawSelection()
    {
        var selStart = SelectionStart();
        var selEnd = SelectionEnd();
        var (startLine, startCol) = LocateCaret(selStart);
        var (endLine, endCol) = LocateCaret(selEnd);

        var font = GetFont(THEME_FONT_DEFAULT);
        var fontSize = _resolvedFontSize > 0 ? _resolvedFontSize : ResolveFontSize();
        var lineHeight = font.GetHeight(fontSize);
        var ascent = font.GetAscent(fontSize);
        var selColor = SelectionColor with { A = 0.5f };

        for (var i = startLine; i <= endLine && i < _lineRids.Count; i++)
        {
            var originX = GetLineDrawOriginX(i);
            var baselineY = GetLineBaselineY(i);
            var topY = baselineY - ascent;

            var leftCol = i == startLine ? startCol : 0;
            var rightCol = i == endLine ? endCol : GetLineShapedLength(i);

            var leftX = originX + GetCaretRelativeXOnLine(i, leftCol);
            var rightX = originX + GetCaretRelativeXOnLine(i, rightCol);
            var content = GetContentRect();
            leftX = Mathf.Max(leftX, content.Position.X);
            rightX = Mathf.Min(rightX, content.Position.X + content.Size.X);
            if (rightX <= leftX) continue;

            DrawRect(new Rect2(leftX, topY, rightX - leftX, lineHeight), selColor);
        }
    }

    private void DrawCaret()
    {
        var font = GetFont(THEME_FONT_DEFAULT);
        var fontSize = _resolvedFontSize > 0 ? _resolvedFontSize : ResolveFontSize();
        var ascent = font.GetAscent(fontSize);
        var lineHeight = font.GetHeight(fontSize);

        var (line, col) = LocateCaret(CaretIndex);
        if (line >= _lineRids.Count) return;

        var caretX = GetLineDrawOriginX(line) + GetCaretRelativeXOnLine(line, col);
        var caretTopY = GetLineBaselineY(line) - ascent;

        DrawRect(new Rect2(caretX, caretTopY, CaretWidth, lineHeight), CaretColor);
    }
    
    private void DrawTextMarks()
