    private void DrawTextMark(TextMark mark)
    {
        var start = Mathf.Clamp(mark.Start, 0, _text.Length);
        var end = Mathf.Clamp(mark.End, start, _text.Length);
        if (start >= end) return;

        var (startLine, startCol) = LocateCaret(start);
        var (endLine, endCol) = LocateCaret(end);

        var font = GetFont(THEME_FONT_DEFAULT);
        var fontSize = _resolvedFontSize > 0 ? _resolvedFontSize : ResolveFontSize();
        var descent = font.GetDescent(fontSize);

        var content = GetContentRect();
        var contentLeft = content.Position.X;
        var contentRight = content.Position.X + content.Size.X;

        for (var line = startLine; line <= endLine && line < _lineRids.Count; line++)
        {
            var rid = _lineRids[line];
            if (!rid.IsValid) continue;

            var originX = GetLineDrawOriginX(line);
            var baselineY = GetLineBaselineY(line);
            var squiggleY = baselineY + descent * 0.5f;

            var leftCol = line == startLine ? startCol : 0;
            var rightCol = line == endLine ? endCol : GetLineShapedLength(line);

            var leftX = originX + GetCaretRelativeXOnLine(line, leftCol);
            var rightX = originX + GetCaretRelativeXOnLine(line, rightCol);

            leftX = Mathf.Max(leftX, contentLeft);
            rightX = Mathf.Min(rightX, contentRight);
            if (rightX <= leftX) continue;

            DrawWavyLine(leftX, rightX, squiggleY, mark.Color);
        }
    }

    private void DrawWavyLine(float x1, float x2, float y, Color color)
    {
        const float PERIOD = 4f;
        const float AMPLITUDE = 1.5f;

        var width = x2 - x1;
        if (width <= 0) return;

        var sampleCount = Mathf.Max(2, Mathf.CeilToInt(width));
        var points = new Vector2[sampleCount];
        for (var k = 0; k < sampleCount; k++)
        {
            var t = (float)k / (sampleCount - 1);
            var x = x1 + t * width;
            var phase = (x - x1) / PERIOD * Mathf.Tau;
            var py = y + AMPLITUDE * Mathf.Sin(phase);
            points[k] = new Vector2(x, py);
        }
        DrawPolyline(points, color);
    }

    private void DrawScrollbar()
    {
        var max = GetMaxScrollOffsetY();
        if (max <= 0f) return;

        var content = GetContentRect();
        var trackX = content.Position.X + content.Size.X - SCROLLBAR_WIDTH;
        var trackY = content.Position.Y;
        var trackHeight = content.Size.Y;

        var font = GetFont(THEME_FONT_DEFAULT);
        var fontSize = _resolvedFontSize > 0 ? _resolvedFontSize : ResolveFontSize();
        var lineHeight = font.GetHeight(fontSize);
        var advance = lineHeight + _lineSpacing;
        var viewportHeight = _maxLines * advance;
        var totalContentHeight = _lineRids.Count * advance;

        var thumbHeight = Mathf.Max(SCROLLBAR_MIN_THUMB_HEIGHT, trackHeight * (viewportHeight / totalContentHeight));
        var thumbY = trackY + (_scrollOffsetY / max) * (trackHeight - thumbHeight);

        var caretColor = CaretColor;
        DrawRect(new Rect2(trackX, trackY, SCROLLBAR_WIDTH, trackHeight), caretColor with { A = 0.15f });
        DrawRect(new Rect2(trackX, thumbY, SCROLLBAR_WIDTH, thumbHeight), caretColor with { A = 0.5f });
    }
 
